"""
Algorithm 1 -- Barning-Hall Tree Enumeration by Bounded Hypotenuse.

Enumerates every primitive Pythagorean triple with odd first leg and hypotenuse at most N,
exactly once, by breadth-first expansion of the root (3,4,5) under the three Berggren
generators.  Correctness rests on two facts: each generator strictly increases the
hypotenuse on admissible nodes with positive legs (so the search terminates and no node
repeats), and every such triple lies in the tree (Barning-Hall completeness).
"""

from __future__ import annotations

from typing import Callable, Dict, Iterator, List, Tuple

Triple = Tuple[int, int, int]
ROOT: Triple = (3, 4, 5)


def gen_A(v: Triple) -> Triple:
    a, b, c = v
    return (a - 2 * b + 2 * c, 2 * a - b + 2 * c, 2 * a - 2 * b + 3 * c)


def gen_B(v: Triple) -> Triple:
    a, b, c = v
    return (a + 2 * b + 2 * c, 2 * a + b + 2 * c, 2 * a + 2 * b + 3 * c)


def gen_C(v: Triple) -> Triple:
    a, b, c = v
    return (-a + 2 * b + 2 * c, -2 * a + b + 2 * c, -2 * a + 2 * b + 3 * c)


GENERATORS: Dict[str, Callable[[Triple], Triple]] = {"A": gen_A, "B": gen_B, "C": gen_C}


def berggren_tree(max_hyp: int) -> Iterator[Tuple[str, Triple, int]]:
    """Yield (address, triple, depth) for every node with hypotenuse <= max_hyp."""
    frontier: List[Tuple[str, Triple]] = [("", ROOT)]
    while frontier:
        nxt: List[Tuple[str, Triple]] = []
        for word, v in frontier:
            yield (word, v, len(word))
            for letter, g in GENERATORS.items():
                child = g(v)
                if child[2] <= max_hyp:
                    nxt.append((word + letter, child))
        frontier = nxt


if __name__ == "__main__":
    nodes = list(berggren_tree(200))
    print(f"{len(nodes)} primitive odd-leg triples with c <= 200")
    for word, v, depth in nodes[:12]:
        print(f"  depth {depth}  address {word!r:>6}  {v}")

"""
Algorithm 2 -- Fermat Descent Address Recovery.

Inverts Algorithm 1: given a primitive Pythagorean triple with odd first leg, recovers its
unique address in the ternary tree.  At each step exactly one of the three inverse
generators produces an admissible primitive triple with strictly smaller hypotenuse; the
descent therefore terminates, and it terminates only at the root (3,4,5).  Reversing the
letters gives the address.  The hypotenuse shrinks by a factor at least 3 at every 'B',
so by the Lyapunov bound 5*3^{#B} <= c <= 5*7^{len} the number of steps is
O(log c) for balanced addresses and at most c/5 in the degenerate parabolic case.
"""

from __future__ import annotations

from typing import Callable, Dict, Optional, Tuple

Triple = Tuple[int, int, int]
ROOT: Triple = (3, 4, 5)


def inv_A(v: Triple) -> Triple:
    a, b, c = v
    return (a + 2 * b - 2 * c, -2 * a - b + 2 * c, -2 * a - 2 * b + 3 * c)


def inv_B(v: Triple) -> Triple:
    a, b, c = v
    return (a + 2 * b - 2 * c, 2 * a + b - 2 * c, -2 * a - 2 * b + 3 * c)


def inv_C(v: Triple) -> Triple:
    a, b, c = v
    return (-a - 2 * b + 2 * c, 2 * a + b - 2 * c, -2 * a - 2 * b + 3 * c)


INVERSES: Dict[str, Callable[[Triple], Triple]] = {"A": inv_A, "B": inv_B, "C": inv_C}


def address_of(v: Triple) -> Optional[str]:
    """Return the Berggren address of a primitive odd-leg triple, or None if invalid."""
    a, b, c = v
    if a * a + b * b != c * c or a % 2 == 0 or min(a, b, c) <= 0:
        return None
    letters = []
    while v != ROOT:
        for name, inv in INVERSES.items():
            w = inv(v)
            if (min(w) > 0 and w[2] < v[2]
                    and w[0] * w[0] + w[1] * w[1] == w[2] * w[2]):
                letters.append(name)
                v = w
                break
        else:
            return None
    return "".join(reversed(letters))


if __name__ == "__main__":
    for t in [(3, 4, 5), (5, 12, 13), (21, 20, 29), (119, 120, 169),
              (33, 56, 65), (4485, 5852, 7373)]:
        print(f"{str(t):>22}  ->  address {address_of(t)!r}")
